def run(raw,version='20260713002400',sha=None,size=None,env=None,tool=TOOL):
 with tempfile.TemporaryDirectory() as d:
  p=Path(d)/f'{version}_fixture.sql';p.write_bytes(raw); cmd=['node',str(tool),'--source',str(p),'--version',version,'--sha256',sha or hashlib.sha256(raw).hexdigest(),'--size',str(len(raw) if size is None else size)];return subprocess.run(cmd,capture_output=True,text=True,env=env)
def vector(raw,version,tool=TOOL):
 r=run(raw,version,tool=tool);assert r.returncode==0,r.stderr;return json.loads(r.stdout)
def oracle(raw):
 r=subprocess.run([str(TestG037StatementVector.oracle)],input=raw,capture_output=True,timeout=10)
 assert r.returncode==0,r.stderr.decode()
 return json.loads(r.stdout)
class TestG037StatementVector(unittest.TestCase):
 @classmethod
 def setUpClass(cls):
  cls.cache=tempfile.TemporaryDirectory();cls.oracle=Path(cls.cache.name)/'g037-parser-oracle'
  subprocess.run(['go','build','-o',str(cls.oracle),'.'],cwd=ORACLE,capture_output=True,check=True,timeout=120)
 @classmethod
 def tearDownClass(cls): cls.cache.cleanup()
 def test_manifest_vectors_are_immutable_and_exact(self):
  rows=json.loads((ROOT/'.github/g034-hosted-migration-closure.v1.json').read_text())['migrations'];self.assertEqual(set(VECTORS),{x['version'] for x in rows})
  for row in rows:
   raw=(ROOT/row['path']).read_bytes();self.assertEqual(row['sha256'],hashlib.sha256(raw).hexdigest());out=vector(raw,row['version']);self.assertEqual(UPSTREAM,out['upstream']);self.assertEqual(VECTORS[row['version']],hashlib.sha256(json.dumps(out['statements'],ensure_ascii=True,separators=(',',':')).encode()).hexdigest())
 def test_all_pinned_upstream_split_fixtures(self):
  self.assertEqual(18,len(FIXTURES))
  self.assertEqual(UPSTREAM_SPLIT_BLOBS,tuple(row[1] for row in FIXTURES))
  for name,blob,encoded,expected in FIXTURES:
   raw=base64.b64decode(encoded);self.assertEqual(blob,subprocess.run(["git","hash-object","--stdin"],input=raw,capture_output=True,check=True).stdout.decode().strip());self.assertEqual(expected,vector(raw,"20260713002400")["statements"],name)
 def test_go_oracle_provenance_and_differential_vectors(self):
  source=(ORACLE/'main.go').read_text();module=(ORACLE/'go.mod').read_text();checksums=(ORACLE/'go.sum').read_text()
  self.assertIn('"github.com/supabase/cli/pkg/parser"',source);self.assertIn('parser.SplitAndTrim',source)
  self.assertIn('github.com/supabase/cli v2.109.1+incompatible',module)
  self.assertIn('github.com/supabase/cli v2.109.1+incompatible h1:XTftT7dQegP+PdZdcQtEhivrtIc8zeRA1yPWvsPsqNw=',checksums)
  resolved=json.loads(subprocess.run(['go','list','-m','-json','github.com/supabase/cli@6d4c19870ed213ba7f682f117d0345c8a40bfa94'],cwd=ORACLE,capture_output=True,text=True,check=True,timeout=30).stdout)
  self.assertEqual('v2.109.1+incompatible',resolved['Version']);self.assertEqual(UPSTREAM['commit'],resolved['Origin']['Hash'])
  parser_dir=Path(subprocess.run(['go','list','-f','{{.Dir}}','github.com/supabase/cli/pkg/parser'],cwd=ORACLE,capture_output=True,text=True,check=True,timeout=30).stdout.strip())
  for part in ('token','state'):
   self.assertEqual(UPSTREAM[part]['blob'],subprocess.run(['git','hash-object',str(parser_dir/f'{part}.go')],capture_output=True,text=True,check=True).stdout.strip())
  rows=json.loads((ROOT/'.github/g034-hosted-migration-closure.v1.json').read_text())['migrations'];self.assertEqual(29,len(rows))
  for name,_,encoded,expected in FIXTURES:
   raw=base64.b64decode(encoded);self.assertEqual(expected,oracle(raw),name);self.assertEqual(vector(raw,'20260713002400')['statements'],oracle(raw),name)
  for row in rows:
   raw=(ROOT/row['path']).read_bytes();self.assertEqual(vector(raw,row['version'])['statements'],oracle(raw),row['version'])
 def test_unicode_decimal_number_runes_match_go_and_reject_legacy_number_categories(self):
  cases=(
   ('Nl tag',b'SELECT $tag\xe2\x85\xab$; SELECT 1; $tag\xe2\x85\xab$;',['SELECT $tagⅫ$','SELECT 1','$tagⅫ$']),
   ('No tag',b'SELECT $tag\xc2\xb2$; SELECT 1; $tag\xc2\xb2$;',['SELECT $tag²$','SELECT 1','$tag²$']),
   ('Nl BEGIN ATOMIC identifier',b'\xe2\x85\xabBEGIN ATOMIC SELECT 1; END; SELECT 2;',['ⅫBEGIN ATOMIC SELECT 1; END','SELECT 2']),
   ('No BEGIN ATOMIC identifier',b'\xc2\xb2BEGIN ATOMIC SELECT 1; END; SELECT 2;',['²BEGIN ATOMIC SELECT 1; END','SELECT 2']),
  )
  with tempfile.TemporaryDirectory() as d:
   legacy=Path(d)/'g037_legacy_number_vector.mjs';source=TOOL.read_text();self.assertEqual(2,source.count(r'\p{Nd}'));legacy.write_text(source.replace(r'\p{Nd}',r'\p{N}'))
   for name,raw,expected in cases:
    self.assertEqual(expected,oracle(raw),name)
    self.assertEqual(expected,vector(raw,'20260713002400')['statements'],name)
    self.assertNotEqual(expected,vector(raw,'20260713002400',legacy)['statements'],name)
 def test_unicode_fold_and_scanner_boundary(self):
  self.assertEqual(['BEGIN ATOMIC SELECT 1; eNd','SELECT 2'],vector('BEGIN ATOMIC SELECT 1; eNd; SELECT 2;'.encode(),'20260713002400')['statements'])
  self.assertEqual(0,run(b'a'*(256*1024-1)+b';').returncode);self.assertNotEqual(0,run(b'a'*(256*1024)).returncode)
 def test_rejects_bad_identity_and_unsupported_input(self):
  self.assertNotEqual(0,run(b'SELECT 1;',sha='0'*64).returncode);self.assertNotEqual(0,run(b'SELECT 1;',size=1).returncode);self.assertNotEqual(0,run(b'\xff').returncode)
  env=dict(__import__('os').environ,SUPABASE_SCANNER_BUFFER_SIZE='1MB');self.assertNotEqual(0,run(b'SELECT 1;',env=env).returncode)
